// Race-only adapter. The existing game, player physics and Time Attack source
// files remain untouched; inactive hooks delegate straight to the originals.
(() => {
'use strict';
const T=window.THREE,OriginalRenderer=T.WebGLRenderer,originalStep=Physics.step;
const api={active:false,controller:null,playerCar:null,scene:null,root:null,models:[],lastFrame:0,data:null,restart:null};window.RaceRuntime=api;
function data(){if(api.data)return api.data;const raw=SPA_DATA.features[0].geometry.coordinates,lon=raw[0][0],lat=raw[0][1];let p=raw.slice(0,-1).map(q=>new T.Vector3((q[0]-lon)*111320*Math.cos(lat*Math.PI/180),0,-(q[1]-lat)*111320));let curve=new T.CatmullRomCurve3(p,true,'centripetal');curve.arcLengthDivisions=60000;curve.updateArcLengths();const scale=7004/curve.getLength();p.forEach(q=>q.multiplyScalar(scale));curve=new T.CatmullRomCurve3(p,true,'centripetal');curve.arcLengthDivisions=60000;curve.updateArcLengths();const elevation=Elevation.create(),track=Array.from({length:1751},(_,i)=>{const q=curve.getPointAt(i/1751);return{x:q.x,y:elevation.height(i/1751),z:q.z};});api.data={track,line:RacingLine.build(track,Physics)};return api.data;}
api.prepare=options=>{const config={...RaceGrid.config(options),...options},d=data();api.config=config;api.controller=RaceCore.create(d.track,d.line,config,Physics,config.seed===undefined?Math.random:RaceCore.seeded(config.seed));api.playerCar=null;api.active=true;api.lastFrame=performance.now();if(api.root&&api.scene)api.scene.add(api.root);if(api.onFrame)api.onFrame();};
api.deactivate=()=>{api.active=false;api.playerCar=null;if(api.root&&api.scene)api.scene.remove(api.root);if(api.onHide)api.onHide();};
Physics.step=function(car,input,dt){if(!api.active)return originalStep(car,input,dt);api.playerCar=car;const state=api.controller.state;if(state.phase!=='racing'||state.player.finished){car.v=0;car.yaw=car.g=car.slip=0;car.steer+=(input.steer-car.steer)*Math.min(1,dt*6);return car;}const result=originalStep(car,input,dt);api.controller.contact(car);return result;};
function carModel(number,color){const g=new T.Group(),body=new T.MeshStandardMaterial({color,roughness:.45}),dark=new T.MeshStandardMaterial({color:'#101715',roughness:.65}),rubber=new T.MeshStandardMaterial({color:'#111412',roughness:1}),white=new T.MeshStandardMaterial({color:'#e2e9e3',roughness:.5});function box(w,h,d,mat,x,y,z){const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);g.add(m);return m;}box(1.1,.43,2.7,body,0,.48,-.1);box(.42,.25,2.25,body,0,.38,1.55);box(1.95,.075,.5,dark,0,.20,2.8);box(1.9,.09,.58,body,0,.96,-1.85);box(.6,.65,1.3,body,0,.75,-.85);for(const side of[-1,1]){box(.09,.5,.12,dark,side*.62,.65,-1.8);box(.36,.4,1.6,body,side*.6,.38,-.2);for(const z of[-1.22,1.65]){const wheel=new T.Mesh(new T.CylinderGeometry(.37,.37,.36,14),rubber);wheel.rotation.z=Math.PI/2;wheel.position.set(side*.96,.37,z);g.add(wheel);}box(1,.045,.12,dark,side*.5,.28,1.55);}const helmet=new T.Mesh(new T.SphereGeometry(.18,12,8),white);helmet.position.set(0,1.02,.14);g.add(helmet);const halo=new T.CatmullRomCurve3([new T.Vector3(-.48,.7,-.3),new T.Vector3(-.48,1.2,.2),new T.Vector3(0,1.16,1),new T.Vector3(.48,1.2,.2),new T.Vector3(.48,.7,-.3)]);g.add(new T.Mesh(new T.TubeGeometry(halo,18,.04,5,false),dark));box(.05,.6,.06,dark,0,.85,1);const canvas=document.createElement('canvas');canvas.width=128;canvas.height=64;const c=canvas.getContext('2d');c.fillStyle='#101715';c.fillRect(0,0,128,64);c.fillStyle='#fff';c.font='bold 45px Arial';c.textAlign='center';c.fillText(String(number).padStart(2,'0'),64,49);const plate=new T.Mesh(new T.PlaneGeometry(.32,.16),new T.MeshBasicMaterial({map:new T.CanvasTexture(canvas),side:T.DoubleSide}));plate.rotation.x=-Math.PI/2;plate.position.set(0,.512,1.6);g.add(plate);g.userData.raceOpponent=true;return g;}
api.carModel=carModel;api.getData=data;
function visuals(scene,dt){if(!api.root){api.root=new T.Group();api.root.userData.raceField=true;const colors=['#d14232','#36becd','#5889e0','#e5a32a','#f0f0dc','#355bcb','#4f9c62','#9d7dce','#d873b7','#6cc3ad'];for(let i=0;i<19;i++){const m=carModel(i+2,colors[Math.floor(i/2)]);api.models.push(m);api.root.add(m);}}if(api.root.parent!==scene)scene.add(api.root);for(let i=0;i<19;i++){const d=api.controller.state.drivers[i],m=api.models[i],p=api.controller.pose(d);m.visible=d.finishTime===null||d.s<api.config.laps*7004+300;const world=d.worldPose||p,target=new T.Vector3(world.x,p.y+.055,world.z);if(api.config.multiplayer&&m.userData.networkPlaced)m.position.lerp(target,1-Math.exp(-dt*18));else m.position.copy(target);m.userData.networkPlaced=!!api.config.multiplayer;m.rotation.set(-Math.atan(p.grade),(d.worldPose?.heading??p.heading)+Math.atan2(d.offsetVelocity,Math.max(5,d.v)),0,'YXZ');}}
api.frame=(scene,camera)=>{api.scene=scene;const now=performance.now(),dt=Math.min(.1,Math.max(0,(now-api.lastFrame)/1000));api.lastFrame=now;const diag=window.racingDiagnostics?.();if(api.config?.multiplayer&&api.beforeAdvance)api.beforeAdvance(dt);else if(!diag?.paused)api.controller.advance(dt,api.playerCar);visuals(scene,dt);if(api.onFrame)api.onFrame();};
T.WebGLRenderer=class RaceRenderer extends OriginalRenderer{constructor(options){super(options);const draw=this.render.bind(this);this.render=(scene,camera)=>{if(api.active)api.frame(scene,camera);draw(scene,camera);};}};
addEventListener('keydown',e=>{if(api.active&&e.code==='KeyR'){e.preventDefault();e.stopImmediatePropagation();api.restart?.();}});
})();
